#include <bits/stdc++.h>
using namespace std;using E=array<int,5>;const int ps[5]={2,3,5,7,11};
int M;vector<pair<int,E>> fac;
int primecost(int p,int d){if(!d)return 0;for(int k=1;k<=12;k++){int s=0;for(int q=M/p;q;q/=p)s+=min(k,q);if(s>=d)return k;}return 13;}
bool pack(E e,int K=12){int cap[12],bin[12];for(int j=0;j<K;j++)cap[j]=M/(j+1);int P[160],N=0;for(int k=4;k>=0;k--)for(int j=0;j<e[k];j++)P[N++]=k;for(int mode=0;mode<3;mode++){fill(bin,bin+K,1);bool ok=true;for(int t=0;t<N;t++){int p=ps[P[t]],best=-1;for(int j=0;j<K;j++){if(bin[j]>cap[j]/p)continue;if(best<0||(mode==1&&cap[j]*bin[best]<cap[best]*bin[j])||(mode==2&&cap[j]*bin[best]>cap[best]*bin[j]))best=j;}if(best<0){ok=false;break;}bin[best]*=p;}if(ok)return true;}return false;}
// A sequence of factors, whose gcd with the previous requirement permits one-point addition.
bool gcdgreedy(E d,int K,int mode){E rem=d,old{};for(int j=1;j<=K;j++){int best=-1;double val=-1;for(int i=0;i<(int)fac.size();i++){auto &[h,e]=fac[i];int g=1,go=0;double s=0;bool ok=true;for(int k=0;k<5;k++){if(e[k]>rem[k]){ok=false;break;}int u=min(old[k],e[k]);go+=u;for(int l=0;l<u;l++)g*=ps[k];if(mode==0)s+=e[k]*log2(ps[k]);if(mode==1)s+=e[k];if(mode==2)s+=e[k]*(double)ps[k];if(mode==3)s+=e[k]/(double)max(1,rem[k]);if(mode==4)s+=e[k]*log2(ps[k])/(double)max(1,rem[k]);if(mode==5)s+=e[k]*(1.+.4*old[k]);}if(!ok)continue;if(g>M/j&&go>1)continue;if(s>val){best=i;val=s;}}if(best<0)return false;auto e=fac[best].second;for(int k=0;k<5;k++){old[k]+=e[k];rem[k]-=e[k];}if(rem==E{})return true;}return false;}
int main(int argc,char**argv){ifstream in(argv[1]);int m;E e;int n=0,b=0,last=0,nb=0;long long cp=0,cg=0;while(in>>m>>e[0]>>e[1]>>e[2]>>e[3]>>e[4]){if(m!=last){if(last)cerr<<last<<" input="<<n<<" bad="<<b<<"\n";n=b=0;last=M=m;fac.clear();for(int h=2;h<=M;h++){int x=h;E z{};for(int i=0;i<5;i++)while(x%ps[i]==0){x/=ps[i];z[i]++;}if(x==1)fac.push_back({h,z});}}n++;if(pack(e)){cp++;continue;}bool good=false;for(int mode=0;mode<6;mode++)if(gcdgreedy(e,12,mode)){good=true;break;}if(good){cg++;continue;}cout<<M;for(int x:e)cout<<" "<<x;cout<<"\n";nb++;b++;}cerr<<last<<" input="<<n<<" bad="<<b<<"\n";cerr<<"PACK="<<cp<<" GCD="<<cg<<" BAD="<<nb<<"\n";}
